import subprocess, os
env=dict(os.environ, HOME="/tmp/nohome")
def fmt(sz, fmt=None):
    p="/tmp/sizefile"
    with open(p,"wb") as f: f.truncate(sz)
    args=["/workspace/executable","-P","-c","-s"]
    if fmt: args+=["-o",fmt]
    args+=[p]
    r=subprocess.run(args,capture_output=True,env=env)
    return r.stdout.decode().split("┌")[0].strip()
for sz in [1050,1150,1250,1350,1450,1550,1650,1750,1850,1950,2050,9950,9949,9951]:
    print(sz, fmt(sz,"si"))
