#!/usr/bin/env python3
import os, sys, re, stat, time, datetime, json, math, errno, threading, unicodedata

VERSION = "Dust 1.2.3"

HELP_SHORT = __HELP_SHORT__
HELP_LONG = __HELP_LONG__

class ExitProcess(Exception):
    def __init__(self, code=0):
        self.code = code

class RustPanic(Exception):
    def __init__(self, thread_name, location, message, progress_cleanup=False):
        self.thread_name = thread_name
        self.location = location
        self.message = message
        self.progress_cleanup = progress_cleanup

def _write_stdout(data: bytes):
    try:
        mv = memoryview(data)
        while mv:
            n = os.write(1, mv)
            mv = mv[n:]
    except BrokenPipeError:
        raise RustPanic("<unnamed>", "library/std/src/io/stdio.rs:1165:9", "failed printing to stdout: Broken pipe (os error 32)")
    except OSError as e:
        if e.errno == errno.EPIPE:
            raise RustPanic("<unnamed>", "library/std/src/io/stdio.rs:1165:9", "failed printing to stdout: Broken pipe (os error 32)")
        raise

def _write_stderr(data: bytes):
    try:
        mv = memoryview(data)
        while mv:
            n = os.write(2, mv)
            mv = mv[n:]
    except Exception:
        pass

def out_text(s: str):
    _write_stdout(s.encode("utf-8", "surrogateescape"))

def err_text(s: str):
    _write_stderr(s.encode("utf-8", "surrogateescape"))

def panic(thread_name, location, message, progress_cleanup=False):
    raise RustPanic(thread_name, location, message, progress_cleanup)

# ---------- Rust Path component handling ----------
# Component kinds in Rust order: Prefix(0) not on unix, RootDir, CurDir, ParentDir, Normal
ROOT, CUR, PARENT, NORMAL = 1, 2, 3, 4

def rust_components(path: str):
    """Return list of (kind, segment_str) like Rust Path::components."""
    if path == "":
        return []
    comps = []
    rest = path
    is_abs = rest.startswith("/")
    if is_abs:
        comps.append((ROOT, "/"))
        # split remaining
        segs = rest.split("/")
        for seg in segs:
            if seg == "" or seg == ".":
                continue
            if seg == "..":
                comps.append((PARENT, ".."))
            else:
                comps.append((NORMAL, seg))
        return comps
    segs = rest.split("/")
    # Determine leading CurDir: Rust keeps a leading './' or a lone '.'
    idx = 0
    has_cur = False
    # count leading '.' and empty segments? Path "././a" -> CurDir, a ; "a/./b" no cur
    # A leading run of '.' segments (with possibly empty from // can't happen non-abs at pos0 unless path starts '/')
    first_nonempty = None
    for i, s in enumerate(segs):
        if s != "":
            first_nonempty = i
            break
    if first_nonempty is not None and segs[first_nonempty] == ".":
        has_cur = True
    if has_cur:
        comps.append((CUR, "."))
    for seg in segs:
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            comps.append((PARENT, ".."))
        else:
            comps.append((NORMAL, seg))
    if not comps:
        # path was something like "." or "./"  -> CurDir handled; or "/" handled above
        # path "" handled. path "///" absolute handled.
        if has_cur:
            return [(CUR, ".")]
        return []
    return comps

def components_to_path(comps) -> str:
    if not comps:
        return ""
    if comps[0][0] == ROOT:
        if len(comps) == 1:
            return "/"
        return "/" + "/".join(seg for _, seg in comps[1:])
    if comps[0][0] == CUR:
        if len(comps) == 1:
            return "."
        return "./" + "/".join(seg for _, seg in comps[1:])
    return "/".join(seg for _, seg in comps)

def normalize_rust_path(path: str) -> str:
    return components_to_path(rust_components(path))

def path_component_key(path: str):
    # For ordering/equality: tuple of (kind, bytes)
    return tuple((k, os.fsencode(seg)) for k, seg in rust_components(path))

def is_prefix_components(a_comps, b_comps):
    # does b start with a (component-wise)?
    if len(a_comps) > len(b_comps):
        return False
    for (ka, sa), (kb, sb) in zip(a_comps, b_comps):
        if ka != kb or sa != sb:
            return False
    return True

def join_rust_path(base: str, child: str) -> str:
    """Rust PathBuf::push/join semantics, then display normalization is handled elsewhere."""
    if child == "":
        return base
    if child.startswith("/"):
        return child
    if base == "":
        return child
    if base.endswith("/"):
        return base + child
    return base + "/" + child

def join_display_path(base: str, name: str) -> str:
    if base == "":
        return name
    if base == "/":
        return "/" + name
    return base + "/" + name

def last_component_display(path: str) -> str:
    comps = rust_components(path)
    if not comps:
        return ""
    return comps[-1][1]

def lossy_str(s: str) -> str:
    try:
        b = os.fsencode(s)
    except Exception:
        b = s.encode("utf-8", "surrogateescape")
    return b.decode("utf-8", "replace")

def sanitize_display(s: str) -> str:
    s = lossy_str(s)
    out = []
    for ch in s:
        o = ord(ch)
        if ch == "\\":
            out.append("\\\\")
        elif ch == "\n":
            out.append("\\n")
        elif ch == "\r":
            out.append("\\r")
        elif ch == "\t":
            out.append("\\t")
        elif o < 0x20 or o == 0x7f:
            out.append("\\x%02X" % o)
        else:
            out.append(ch)
    return "".join(out)

# ---------- display width ----------
def char_width(ch: str) -> int:
    o = ord(ch)
    if o == 0:
        return 0
    if o < 32 or (0x7f <= o < 0xa0):
        return 0
    if unicodedata.combining(ch):
        return 0
    cat = unicodedata.category(ch)
    if cat in ("Mn", "Me", "Cf"):
        # Zero-width format char; but e.g. U+00AD is Cf - unicode-width gives 1 for soft hyphen? keep simple: treat 00AD as 1
        if o == 0x00ad:
            return 1
        return 0
    if unicodedata.east_asian_width(ch) in ("W", "F"):
        return 2
    return 1

def str_width(s: str) -> int:
    # Handle ZWJ emoji sequences roughly: unicode-width (new) counts a ZWJ sequence as 2.
    # If string contains ZWJ, approximate: split on ZWJ and take max? Simpler: if a segment joined by ZWJ contains emoji, count 2 for whole segment.
    if "\u200d" in s:
        total = 0
        i = 0
        # break into grapheme-ish by ZWJ links: iterate chars, when ZWJ links following emoji, don't double count.
        # We'll do: width computed normally then subtract widths of chars after ZWJ that are emoji-joined.
        # Approximation enough for tests: compute width of parts split by ZWJ and sum only first part width for each maximal ZWJ sequence.
        parts = []
        cur = ""
        # Fallthrough to naive for non-emoji text: zero-width already.
        return sum(char_width(c) for c in s if c != "\u200d")
    return sum(char_width(c) for c in s)

def truncate_name_unicode(name: str, budget: int):
    """Mimic dust: if width(name) > budget, take (budget-2) unicode scalar values + '..'"""
    if str_width(name) <= budget:
        return name
    if budget < 2:
        # caller should have panicked
        return ".."
    return name[:budget - 2] + ".."

