# ---------- size formatting ----------
_UNITS = ["B", "K", "M", "G", "T", "P"]

def _human_size(size: int, base: int) -> str:
    if size < base:
        return f"{size}B"
    idx = 1
    # largest idx such that size >= base**idx, capped at 5
    while idx < 5 and size >= (base ** (idx + 1)):
        idx += 1
    divisor = base ** idx
    if size < 10 * divisor:
        val = size / divisor
        return f"{val:.1f}{_UNITS[idx]}"
    else:
        return f"{size // divisor}{_UNITS[idx]}"

def format_bytes(size: int, fmt) -> str:
    size = int(size) & ((1 << 64) - 1) if int(size) >= 0 else int(size)
    if fmt is None:
        return _human_size(size, 1024)
    s = fmt
    lower = s.lower()
    if lower == "si":
        return _human_size(size, 1000)
    if lower and lower[0] in "bkmgtp":
        power = "bkmgtp".index(lower[0])
        byte_len = len(s.encode("utf-8", "surrogateescape"))
        base = 1024 if (byte_len == 1 or "i" in lower) else 1000
        divisor = base ** power
        return f"{size // divisor}{_UNITS[power]}"
    byte_len = len(s.encode("utf-8", "surrogateescape"))
    base = 1000 if (byte_len > 1 and "i" not in lower) else 1024
    return _human_size(size, base)

def format_filetime(epoch: int) -> str:
    # epoch is already absolute seconds (for display)
    try:
        lt = time.localtime(int(epoch))
    except Exception:
        # fallback to UTC via datetime
        try:
            dt = datetime.datetime.utcfromtimestamp(int(epoch))
            lt = dt.timetuple()
        except Exception:
            return "1970-01-01T00:00:00"
    return "%04d-%02d-%02dT%02d:%02d:%02d" % (lt.tm_year, lt.tm_mon, lt.tm_mday, lt.tm_hour, lt.tm_min, lt.tm_sec)

