def parse_min_size(s):
    """Return int or None; prints warning for invalid suffix (mirroring reference)."""
    if s is None:
        return None
    m = re.search(r"(\d+)(\w*)", s, flags=re.UNICODE)
    if not m:
        return None
    num_str, suffix = m.group(1), m.group(2)
    if not num_str.isascii():
        return None
    try:
        num = int(num_str)
    except Exception:
        return None
    if num > (1 << 64) - 1:
        return None
    if suffix == "":
        return num
    first = suffix[0].lower()
    if first not in "bkmgtp":
        err_text(f"Ignoring invalid min-size: {s}\n")
        return None
    power = "bkmgtp".index(first)
    lower_suf = suffix.lower()
    byte_len = len(suffix.encode("utf-8", "surrogateescape"))
    base = 1024 if (byte_len == 1 or "i" in lower_suf) else 1000
    return (num * (base ** power)) & ((1 << 64) - 1)

