            fg = None
        elif 40 <= code <= 47:
            bg = ("n", code)
        elif code == 49:
            bg = None
        elif 90 <= code <= 97:
            fg = ("f", code - 90 + 8)
        elif 100 <= code <= 107:
            bg = ("f", code - 100 + 8)
        else:
            return None
