class LsColors:
    def __init__(self):
        self.indicators = {}
        # render defaults
        for k, v in _LS_DEFAULT.items():
            self.indicators[k] = _render_ls_style(v) if v is not None else None
        # fix-ups where default raw string rendering would reorder incorrectly:
        # our renderer already renders bg first, so "41;37" stays 41;37 etc, "1;34" -> 1;34 fine.
        self.extensions = {}  # lowercased extension (without dot) -> rendered style or None
        env = os.environ.get("LS_COLORS")
        if env:
            for item in env.split(":"):
                if not item:
                    continue
                if "=" not in item:
                    continue
                key, val = item.split("=", 1)
                style = _render_ls_style(val)
                if key.startswith("*"):
                    # store by extension after last dot
                    if "." in key:
                        ext = key.rsplit(".", 1)[-1].lower()
                        self.extensions[ext] = style
                    continue
                # two-letter indicators only known
                self.indicators[key] = style
    def style_for(self, filename: str, follow_stat):
        """follow_stat: os.stat_result or None (metadata following links)."""
        # filename: basename string (lossy not needed); use for extension
        if follow_stat is not None:
            mode = follow_stat.st_mode
            if stat.S_ISDIR(mode):
                sticky = bool(mode & 0o1000)
                owrite = bool(mode & 0o002)
                if sticky and owrite:
                    ind = "tw"
                elif owrite:
                    ind = "ow"
                elif sticky:
                    ind = "st"
                else:
                    ind = "di"
                return self.indicators.get(ind)
            if stat.S_ISFIFO(mode):
                return self.indicators.get("pi")
            if stat.S_ISSOCK(mode):
                return self.indicators.get("so")
            if stat.S_ISBLK(mode):
                return self.indicators.get("bd")
            if stat.S_ISCHR(mode):
                return self.indicators.get("cd")
            if stat.S_ISREG(mode):
                if mode & 0o4000:
                    return self.indicators.get("su")
                if mode & 0o2000:
                    return self.indicators.get("sg")
                if mode & 0o111:
                    return self.indicators.get("ex")
                if getattr(follow_stat, "st_nlink", 1) > 1:
                    mh = self.indicators.get("mh")
                    if mh is not None:
                        return mh
                    # if mh has no style, GNU falls through to extension/fi? In reference custom mh=45 used mh; default mh None then file had no style (fi also None).
                    # Continue to extension check
                ext_style = self._ext_style(filename)
                if ext_style is not _MISSING:
                    return ext_style
                return self.indicators.get("fi")
            # other types
            return self.indicators.get("fi")
        else:
            ext_style = self._ext_style(filename)
            if ext_style is not _MISSING:
                return ext_style
            return self.indicators.get("fi")
    def _ext_style(self, filename):
        # Rust Path::extension on filename
        ext = rust_extension(filename)
        if ext is None:
            return _MISSING
        key = ext.lower()
        if key in self.extensions:
            return self.extensions[key]
        return _MISSING

class _Missing: pass
_MISSING = _Missing()

def rust_extension(filename: str):
    """Return extension string (may be '') or None, per Rust Path::extension on a file name."""
    if filename == "" or filename == "." or filename == "..":
        return None
    idx = filename.rfind(".")
    if idx <= 0:
        return None
    return filename[idx + 1:]

