        if key is not None:
            if key in seen:
                return None
            seen.add(key)
        new_children = []
        for c in node.children:
            r = rec(c)
            if r is not None:
                new_children.append(r)
        node.children = new_children
        builder._aggregate(node)
        return node
    out = []
    for r in roots:
        rr = rec(r)
        if rr is not None:
            out.append(rr)
    return out

