def dedup_roots(roots, builder):
    if builder.opts.apparent_size:
        return roots
    seen = set()
    def rec(node):
        key = node.dedup_key
        if key is not None:
            if key in seen:
                return None
            seen.add(key)
        new_children = []
        for c in node.children:
            r = rec(c)
            if r is not None:
                new_children.append(r)
        node.children = new_children
        builder._aggregate(node)
        return node
    out = []
    for r in roots:
        rr = rec(r)
        if rr is not None:
            out.append(rr)
    return out

def sort_tree(node):
    node.children.sort(key=lambda n: (n.size, path_component_key(n.name)), reverse=True)
    for c in node.children:
        sort_tree(c)

