# ---------- display ----------
class DisplayLine:
    __slots__ = ("node", "level", "indent_units", "branch", "is_biggest", "ancestors")
    def __init__(self, node, level, indent_units, branch, is_biggest, ancestors):
        self.node = node; self.level = level; self.indent_units = indent_units; self.branch = branch; self.is_biggest = is_biggest; self.ancestors = ancestors

def _format_size_for(node_size, opts, for_json=False):
    if opts.filecount:
        return str(node_size)
    if opts.filetime and not for_json:
        return format_filetime(node_size)
    return format_bytes(node_size, opts.output_format)

def flatten_display(root, opts):
    lines = []
    reverse = opts.reverse
    root_level = -1 if opts.skip_total else 0
    # recursive walk
    def walk(node, level, indent_units, is_biggest, edge_sibling, ancestors, is_display_root=False):
        # ancestors: list of (level, size) for ancestors (excluding self), nearest last
        # branch chars
        if reverse:
            first = "└" if edge_sibling else "├"
            third = "┬" if node.children else "─"
        else:
            first = "┌" if edge_sibling else "├"
            third = "┴" if node.children else "─"
        branch = first + "─" + third
        line = DisplayLine(node, level, list(indent_units), branch, is_biggest, list(ancestors))
        # children order and flags
        internal = node.children  # sorted descending
        if reverse:
            if not (is_display_root and opts.skip_total):
                lines.append(line)
            for idx, child in enumerate(internal):
                child_edge = (idx == len(internal) - 1)
                child_biggest = (idx == 0)
                # indent unit for children: append unit for current node unless current is skipped root (level<0)
                child_indent = list(indent_units)
                if level >= 0:
                    child_indent.append(not edge_sibling)
                child_anc = ancestors + [(level, node.size)]
                walk(child, level + 1, child_indent, child_biggest, child_edge, child_anc, False)
        else:
            asc = list(reversed(internal))
            for idx, child in enumerate(asc):
                child_edge = (idx == 0)
                # biggest is first internal = last in asc
                child_biggest = (child is internal[0]) if internal else False
                child_indent = list(indent_units)
                if level >= 0:
                    child_indent.append(not edge_sibling)
                child_anc = ancestors + [(level, node.size)]
                walk(child, level + 1, child_indent, child_biggest, child_edge, child_anc, False)
            if not (is_display_root and opts.skip_total):
                lines.append(line)
    walk(root, root_level, [], True, True, [], True)
    return lines

def _node_display_name(node, opts):
    if node.name in ("(total)", "(others)", "(no extension)") or getattr(node, "_is_filetype", False):
        return sanitize_display(node.name)
    # Detect filetype nodes: parent handling not available; filetype root children have rel_depth 1 and name not containing '/' and root is (total) - caller in filetypes handles names as-is because full_paths vs last component same for a label without '/'.
    if opts.full_paths:
        return sanitize_display(node.name)
    return sanitize_display(last_component_display(node.name))

def _percent_str(node_size, root_size):
    if root_size == 0:
        pct = 0.0
    else:
        pct = node_size * 100.0 / root_size
    return f"{pct:.0f}"

def _bar_boundary(size, root_size, usable):
    if usable <= 0:
        return 0
    if root_size == 0:
        return 1
    b = int(size * usable // root_size) + 1 if root_size else 1
    if b > usable: b = usable
    return b

def _make_bar(line, root_size, bar_len, bars_on_right):
    # bar_len is inner length between delimiters
    usable = bar_len - 1
    if usable < 1:
        usable = 1
    node = line.node
    # segments: list of (boundary, char) in order own, nearest ancestor, ..., farthest (ancestors list is root..parent; nearest is last)
    segs = []
    segs.append((_bar_boundary(node.size, root_size, usable), "█"))
    # ancestors with level>=1, nearest first
    for lvl, sz in reversed(line.ancestors):
        if lvl < 1:
            continue
        ch = "░" if lvl == 1 else ("▒" if lvl == 2 else "▓")
        segs.append((_bar_boundary(sz, root_size, usable), ch))
    # build char array of length usable, fill spaces
    arr = [" "] * usable
    prev = 0
    for bound, ch in segs:
        if bound > usable: bound = usable
        for k in range(prev, bound):
            arr[k] = ch
        if bound > prev: prev = bound
