    lines_all = flatten_display(root, opts)  # for size width etc, note if skip_total root excluded, size width must include root? Reference: size width based on all display nodes including root even if skipped.
    # Recompute a lines list including root for sizing when skip_total: temporarily flatten without skip by toggling? Instead compute sizes from tree nodes in pruned tree (all nodes).
    all_nodes = []
    stack = [root]
