    # name_part = indent_str + branch + (space unless filetime) + name
    line_infos = []
    for ln in lines_all:
        indent = "".join(("│ " if u else "  ") for u in ln.indent_units)
        name = _node_display_name(ln.node, opts)
        line_infos.append((ln, indent, name))
    # max name_part visual length (indent + branch + (1 if not filetime space counted?) )
    # For bar start calculation, name_part includes branch + space (normal) ; for filetime printed branch has no space but max is based on printed? Earlier analysis: bar-mode (padded filetime) lengths were based on printed (no space). Use printed.
    def name_part_len(indent, branch, name):
        sp = 0 if opts.filetime else 1
        return str_width(indent) + str_width(branch) + sp + str_width(name)
    max_name_part = 0
    for ln, indent, name in line_infos:
        l = name_part_len(indent, ln.branch, name)
        if l > max_name_part: max_name_part = l
    bar_start = size_width + 1 + max_name_part
    show_bars = (not opts.no_percent_bars) and (term_width >= bar_start + 9)
    bar_len = term_width - bar_start - 7 if show_bars else 0
    root_size = root.size
    for ln, indent, name in line_infos:
        node = ln.node
        size_str = _format_size_for(node.size, opts)
        size_padded = size_str.rjust(size_width)
        if use_colors and ln.is_biggest:
            size_disp = f"\x1b[31m{size_padded}\x1b[0m"
        else:
            size_disp = size_padded
        branch = ln.branch
        # Determine name handling
        if show_bars:
            # filetime: bars are not drawn, but name is padded to max (as observed) and no percent
            if opts.filetime:
                # padded name segment: name + padding to fill name_part
                this_len = name_part_len(indent, branch, name)
                pad = max_name_part - this_len
                name_seg_plain = name + (" " * pad)
                name_seg = _colorize_name(name_seg_plain, node, use_colors, lscolors, opts)
                line_str = f"{size_disp} {indent}{branch}{name_seg}\n"
                out_text(line_str)
            else:
                this_len = name_part_len(indent, branch, name)
                pad = max_name_part - this_len
                name_seg_plain = name + (" " * pad)
                name_seg = _colorize_name(name_seg_plain, node, use_colors, lscolors, opts)
                bar = _make_bar(ln, root_size, bar_len, opts.bars_on_right)
                pct = _percent_str(node.size, root_size)
                line_str = f"{size_disp} {indent}{branch} {name_seg}│{bar}│ {pct:>3}%\n"
                out_text(line_str)
        else:
            # no bars: truncate name if needed
            # indent_len for budget: indent + branch + space (even for filetime, phantom space)
            indent_len_budget = str_width(indent) + str_width(branch) + 1
            remaining = term_width - (size_width + 1 + indent_len_budget)
            if remaining < 2:
                panic("<unnamed>", "src/display.rs:308:5", "Terminal width not wide enough to draw directory tree")
            disp_name = truncate_name_unicode(name, remaining)
            name_seg = _colorize_name(disp_name, node, use_colors, lscolors, opts)
            if opts.filetime:
                line_str = f"{size_disp} {indent}{branch}{name_seg}\n"
            else:
                line_str = f"{size_disp} {indent}{branch} {name_seg}\n"
            out_text(line_str)

def _colorize_name(name_seg_plain, node, use_colors, lscolors, opts):
    if not use_colors:
        return name_seg_plain
    # filename for style: basename of node.name (actual path)
    comps = rust_components(node.name)
    fname = comps[-1][1] if comps else node.name
    style = lscolors.style_for(fname, node.follow_stat) if lscolors else None
    if style:
        return f"\x1b[{style}m{name_seg_plain}\x1b[0m"
    return name_seg_plain

def _display_screen_reader(lines, root, opts, size_width, use_colors, lscolors):
    # name width = max display name width
    names = [_node_display_name(ln.node, opts) for ln in lines]
    name_width = max((str_width(n) for n in names), default=0)
    root_size = root.size
    for ln, name in zip(lines, names):
        # pad name to name_width (by visual width)
        pad = name_width - str_width(name)
        name_padded = name + (" " * pad)
        name_seg = _colorize_name(name_padded, ln.node, use_colors, lscolors, opts)
        size_str = _format_size_for(ln.node.size, opts)
        size_padded = size_str.rjust(size_width)
        if use_colors and ln.is_biggest:
            size_disp = f"\x1b[31m{size_padded}\x1b[0m"
        else:
            size_disp = size_padded
        pct = _percent_str(ln.node.size, root_size)
        out_text(f"{name_seg} {ln.level} {size_disp} {pct:>3}%\n")

def print_json(root, opts):
    # Check for invalid UTF-8 in any node name (serde_json PathBuf serialization fails)
    stack = [root]
    while stack:
        nd = stack.pop()
        try:
