    # In prepare, min-size filter applies only if parsed is not None. If parse returned None (invalid/no digits), no filtering.
    # Normalize & dedup inputs (syntactic)
    norm_paths = [normalize_rust_path(p) for p in raw_paths]
    comp_list = [rust_components(p) for p in norm_paths]
    retained = []
    retained_comps = []
    for idx, p in enumerate(norm_paths):
        comps = comp_list[idx]
        drop = False
        for jdx, other in enumerate(comp_list):
            if jdx == idx: continue
            if is_prefix_components(other, comps):
                if other == comps and jdx > idx:
                    continue
                drop = True; break
        if not drop:
            retained.append(p); retained_comps.append(comps)
    norm_paths = retained
    # collapse matcher (textual per-root join)
    collapse_set = set()
    for root_p in norm_paths:
        for col in opts.collapse:
