    opts._progress_started = progress_enabled
    roots = []
    for rp in norm_paths:
        node = builder.build_root(rp)
        if node is not None:
            roots.append(node)
    roots = dedup_roots(roots, builder)
    # Sort each root tree
    for r in roots:
        sort_tree(r)
