    if opts.file_types:
        display_root = build_filetypes_root(roots, opts, effective_n)
    else:
        if len(roots) == 1:
            display_root = roots[0]
        elif len(roots) == 0:
            display_root = Node("(total)", 0, is_dir=False, is_file=False, rel_depth=0)
            display_root.children = []
        else:
            display_root = make_pseudo_total(roots, opts)
            sort_tree(display_root)
    # prepare (transform + prune); filetypes already limited
    display_root = prepare_display_tree(display_root, opts, effective_n)
