    bad_list = list(builder.bad.keys())
    if bad_list:
        err_text("No such file or directory: " + ", ".join(bad_list) + "\n")
    perm_list = list(builder.perm.keys())
    if perm_list:
        if opts.print_errors:
            err_text("Did not have permissions for directories: " + ", ".join(perm_list) + "\n")
        else:
            err_text("Did not have permissions for all directories (add --print-errors to see errors)\n")
    if bad_list and not display_root.children:
        return 1
    use_colors = False
    if opts.force_colors:
        use_colors = True
    elif opts.no_colors:
        use_colors = False
    elif "NO_COLOR" in os.environ:
        use_colors = False
    elif term is not None:
        use_colors = True
    if opts.output_json:
        print_json(display_root, opts)
        return 0
    lscolors = LsColors() if use_colors else None
    display_tree(display_root, opts, term_width, use_colors, lscolors)
