        except BaseException:
            # Unexpected internal errors: mimic a panic-ish failure rather than silent
            import traceback
            traceback.print_exc()
            _result["code"] = 101
    try:
        threading.stack_size(256 * 1024 * 1024)
    except Exception:
        try: threading.stack_size(64 * 1024 * 1024)
        except Exception: pass
    t = threading.Thread(target=_runner)
    t.start(); t.join()
    sys.exit(_result["code"])
